import {wheelVisualDefaults} from './vehicle-wheel-bones.js';
export function wheelBoneControls(wheel,attr,esc,off=''){
 const p={...wheelVisualDefaults(),...wheel.visual};return '<details class="vehicle-wheel-bone"><summary>골격 휠 표시</summary><label>뼈 이름<input type="text" maxlength="160" value="'+esc(p.bone)+'" '+attr('visual.bone')+off+'></label>'+(p.bone?['steerAxis','spinAxis'].map(key=>'<fieldset><legend>'+(key==='steerAxis'?'조향 로컬 축':'회전 로컬 축')+'</legend>'+p[key].map((v,i)=>'<label>'+['X','Y','Z'][i]+'<input type="number" value="'+v+'" step=".1" '+attr('visual.'+key)+' data-wheel-axis="'+i+'"'+off+'></label>').join('')+'</fieldset>').join('')+[['steerScale','조향 배율'],['spinScale','회전 배율'],['suspensionScale','서스펜션 배율']].map(([key,label])=>'<label>'+label+'<input type="number" value="'+p[key]+'" min="-100" max="100" step=".1" '+attr('visual.'+key)+off+'></label>').join(''):'')+'</details>';
}
export function editWheelVisual(wheel,input){const key=input.dataset.wheelKey.slice(7);if(!Object.hasOwn(wheelVisualDefaults(),key))throw Error('차량 휠 표시 속성을 확인하세요.');const p={...wheelVisualDefaults(),...wheel.visual};if(input.dataset.wheelAxis!==undefined){const index=Number(input.dataset.wheelAxis);if(!['steerAxis','spinAxis'].includes(key)||!Number.isInteger(index)||index<0||index>2)throw Error('차량 휠 표시 축을 확인하세요.');p[key]=[...p[key]];p[key][index]=Number(input.value);}else p[key]=key==='bone'?input.value:Number(input.value);wheel.visual=p;}
